const MOD: i32 = 1_000_000_007;

fn number_of_unique_good_subsequences(binary: String) -> i32 {
    let mut one = 0;
    let mut zero = 0;
    let mut extra = 0;
    for c in binary.chars() {
        if c == '1' {
            one = (one + 1 + zero) % MOD;
        } else {
            extra = 1;
            zero = (zero + one) % MOD;
        }
    }

    (one + zero + extra) % MOD
}

pub fn main() {
    let binary = "".to_string();
    println!("{}", number_of_unique_good_subsequences(binary));
}
